# Public checks — run these as often as you like.
def _check_smallest_n() -> None:
    assert smallest_n_for_power([10, 20, 30, 40], [0.5, 0.7, 0.85, 0.95], 0.8) == 30, (
        "30 is the first size whose power (0.85) reaches 0.8"
    )
